/** Reachable Main/Tonight/Wind-down/Alarms journey. All timer and playback boundaries are fake. */
@org.junit.runner.RunWith(androidx.test.ext.junit.runners.AndroidJUnit4.class)
public final class NapIntegrationFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice ui=UiDevice.getInstance(i);MainActivity main;Activity current;
 final class Fixture implements AutoCloseable {
  final String name="nap-integration-"+UUID.randomUUID(),database=name+".db";final SharedPreferences plan=c.getSharedPreferences(name,Context.MODE_PRIVATE);final Records.Factory records=Records.factory;final Naps.Ports ports=Naps.ports;final java.util.function.Function<Context,NapPlan.Clock> clocks=Naps.clocks;final java.util.function.BooleanSupplier tracking=Naps.activeTracking;final java.util.function.LongSupplier tonightClock=TonightScreen.clock;final SleepPlans.Factory plans=SleepPlans.factory;final AlarmScheduling.Port scheduling=AlarmScheduling.port;final AlarmToneAudio.Provider audio=AlarmToneAudio.provider;final TimeZone zone=TimeZone.getDefault();final Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());final List<Activity> owned=new CopyOnWriteArrayList<>();final Application app=(Application)c.getApplicationContext();final NapFlowTest.Clock clock=new NapFlowTest.Clock();String sentinel;int schedules,fires;
  final NapEngine.Port port=new NapEngine.Port(){public String access(){return "";}public void schedule(int id,NapPlan p,long delay){assertTrue(delay>0);schedules++;}public void cancel(int id,NapPlan p){}public void fire(int id,NapPlan p){fires++;throw new AssertionError("No native delivery is expected in this configuration flow");}};
  final Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue("Only Main and Nap configuration may launch",a instanceof MainActivity||a instanceof NapActivity);owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){current=a;if(a instanceof MainActivity)main=(MainActivity)a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
  Fixture()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",ui.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));clock.wall=Instant.parse("2026-10-24T20:00:17.345Z").toEpochMilli();assertTrue(plan.edit().putInt("bedtime",1350).putInt("wakeTime",390).putInt("goal",480).commit());try(Store store=new Store(c,database)){Alarm other=new Alarm(1);other.label="Untouched private alarm";other.enabled=false;store.save(other);sentinel=other.json().toString();}app.registerActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{TimeZone.setDefault(TimeZone.getTimeZone("UTC"));Records.factory=context->new Store(context,database);SleepPlans.factory=context->plan;TonightScreen.clock=()->clock.wall;Naps.clocks=context->clock;Naps.ports=context->port;Naps.activeTracking=()->false;AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){throw new AssertionError("Nap toggles must not use calendar scheduling");}public void schedule(Context context,Alarm alarm){throw new AssertionError("No real or recurring scheduling");}};AlarmToneAudio.provider=context->new AlarmTonePreview.Port(){public AlarmTonePreview.Session open(String tone,float gain,AlarmTonePreview.Events events){throw new AssertionError("No preview action in integration flow");}public void close(){}};Appearance.save(c,false,0,0,true,false);});}
  Alarm nap(int id){try(Store store=new Store(c,database)){return store.alarm(id);}}
  @Override public void close()throws Exception{try{i.runOnMainSync(()->owned.forEach(a->{if(!a.isDestroyed())a.finish();}));i.waitForIdleSync();long end=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));try(Store store=new Store(c,database)){assertEquals(sentinel,store.alarm(1).json().toString());assertEquals(0,store.backup().getJSONArray("sessions").length());assertEquals(0,store.backup().getJSONArray("epochs").length());}assertEquals(0,fires);assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{TimeZone.setDefault(zone);Records.factory=records;Naps.ports=ports;Naps.clocks=clocks;Naps.activeTracking=tracking;TonightScreen.clock=tonightClock;SleepPlans.factory=plans;AlarmScheduling.port=scheduling;AlarmToneAudio.provider=audio;SharedPreferences.Editor edit=Prefs.of(c).edit();for(String key:new String[]{Appearance.AUTO,Appearance.THEME,Appearance.SIZE,Appearance.MOTION,Appearance.CONTRAST}){Object value=original.get(key);if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else edit.remove(key);}assertTrue(edit.commit());});assertEquals(original,Prefs.of(c).getAll());if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(database);c.deleteSharedPreferences(name);}}}
 }
 void launch()throws Exception{Instrumentation.ActivityMonitor m=i.addMonitor(MainActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,MainActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));main=(MainActivity)m.waitForActivityWithTimeout(5000);assertNotNull(main);}finally{i.removeMonitor(m);}i.waitForIdleSync();}
 void text(String text){assertTrue(text,ui.wait(Until.hasObject(By.text(text)),5000));}
 void state(String text){assertTrue(text,ui.wait(Until.hasObject(By.descContains(text)),5000));}
 void clickText(String value)throws Exception{UiObject2 v=ui.wait(Until.findObject(By.text(value)),2000);if(v==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(value,scroll.exists());scroll.scrollIntoView(new UiSelector().text(value));v=ui.wait(Until.findObject(By.text(value)),2000);}assertNotNull(value,v);v.click();ui.waitForIdle();}
 void desc(String value)throws Exception{UiObject2 v=ui.wait(Until.findObject(By.desc(value)),2000);if(v==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(value,scroll.exists());scroll.scrollIntoView(new UiSelector().description(value));v=ui.wait(Until.findObject(By.desc(value)),2000);}assertNotNull(value,v);v.click();ui.waitForIdle();}
 void capture(String name)throws Exception{CountDownLatch frame=new CountDownLatch(1);boolean[] ready={false};long end=SystemClock.elapsedRealtime()+5000;while(!ready[0]&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{if(current==null||current.isDestroyed()||!current.hasWindowFocus())return;View v=current.getWindow().getDecorView();if(v.isAttachedToWindow()&&v.isHardwareAccelerated()){v.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);v.invalidate();ready[0]=true;}});if(!ready[0])SystemClock.sleep(50);}assertTrue("Focused actual integration window",ready[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(ui.takeScreenshot(new File(folder,"nap-integration-"+name+".png")));}
 @Test public void futureNapUsesRelativeWindowAcrossClockAndZoneChangesAndRealMainRoutes()throws Exception{try(Fixture f=new Fixture()){Alarm draft=new Alarm(0);draft.smartWindow=0;Alarm saved=Naps.start(c,draft,20,f.clock.wall+49*3600000L,false);int id=saved.id;String nonce=saved.nap.nonce;try(Store store=new Store(c,f.database)){Alarm earlier=new Alarm(id+1);earlier.hour=7;earlier.minute=0;earlier.enabled=true;store.save(earlier);assertEquals(earlier.id,Naps.next(c,store.alarms(),f.clock.wall,ZoneId.systemDefault()).alarm.id);earlier.days.add(5);store.save(earlier);assertEquals(id,Naps.next(c,store.alarms(),f.clock.wall,ZoneId.systemDefault()).alarm.id);store.deleteAlarm(earlier.id);}launch();state("Nap starts ");state("20 min planned");state("Nap starts in 49 h");assertFalse(ui.hasObject(By.desc("Monday")));text("NAP ENDS · MON 26 OCT");capture("future");long deadline=saved.nap.projectedDeadline(f.clock);i.runOnMainSync(()->{f.clock.wall+=3*3600000L;main.refreshTonightClock();});state("Nap starts in 49 h");text("NAP ENDS · TUE 27 OCT");assertEquals(deadline+3*3600000L,f.nap(id).nap.projectedDeadline(f.clock));capture("clock-shift");i.runOnMainSync(()->{TimeZone.setDefault(TimeZone.getTimeZone("Asia/Riyadh"));main.refreshTonightClock();});text(Naps.display(c,f.nap(id)));state("20 min planned");capture("zone");clickText("Wind-down at");text("Wind-down");text("Nap");text(Naps.display(c,f.nap(id)));capture("wind-down");clickText("Nap");text("Cancel nap");assertTrue(current instanceof NapActivity);clickText("Cancel nap");assertFalse(f.nap(id).enabled);assertEquals(NapPlan.Phase.CANCELLED,f.nap(id).nap.phase);desc("Back");text("Wind-down");desc("Back");desc("Alarms");text("Alarms");desc("Enable 20 minute nap");text("Start nap");assertTrue(current instanceof NapActivity);assertFalse(f.nap(id).enabled);assertEquals(nonce,f.nap(id).nap.nonce);assertEquals(1,f.schedules);capture("inactive");clickText("Start nap");text("Cancel nap");assertTrue(f.nap(id).enabled);assertNotEquals(nonce,f.nap(id).nap.nonce);assertEquals(1200000,f.nap(id).nap.remaining(f.clock));capture("started");desc("Back");text("Alarms");desc("Enable 20 minute nap");assertFalse(f.nap(id).enabled);desc("Edit 20 minute nap");text("Start nap");clickText("Remove saved nap");text("Remove this nap?");clickText("Remove nap");text("Multiple naps");text("No saved naps");assertNull(f.nap(id));capture("removed");assertEquals(2,f.schedules);desc("Back");desc("Back");text("Alarms");org.json.JSONObject broken=saved.json();broken.getJSONObject("nap").put("minutes","twenty");Alarm malformed=Alarm.read(broken);assertTrue(malformed.napInvalid);try(Store store=new Store(c,f.database)){store.save(malformed);}i.runOnMainSync(main::recreate);text("Review");desc("Edit 20 minute nap");text("This nap could not be read.");capture("invalid");try(Store store=new Store(c,f.database)){assertTrue(store.alarm(id).napInvalid);assertEquals("twenty",store.alarm(id).json().getJSONObject("nap").getString("minutes"));store.deleteAlarm(id);}}}
}
